<?php $this->load->view('frontend/evaluation_header'); $attended=(int)$invitation->registration_status===5; $confirmed=!empty($invitation->profile_confirmed_at); $completed=!empty($invitation->completed_at); $ready=$attended&&$confirmed&&$completed; ?>
<div class="card eval-card"><div class="card-body p-4 p-md-5"><h1 class="h3">สถานะของคุณ</h1><p class="text-secondary"><?= html_escape($assignment->course_title) ?> · <?= html_escape($assignment->batch_no) ?></p>
<?php foreach(array('success'=>'success','error'=>'danger') as $key=>$class): if($this->session->flashdata($key)): ?><div class="alert alert-<?= $class ?>"><?= html_escape($this->session->flashdata($key)) ?></div><?php endif; endforeach; ?>
<div class="border rounded-3 p-3 mb-3"><strong><?= html_escape($invitation->title_name.$invitation->first_name.' '.$invitation->last_name) ?></strong><div><?= html_escape($invitation->email) ?></div><div class="text-secondary"><?= html_escape($invitation->school_name) ?></div><a class="btn btn-sm btn-outline-secondary mt-2" href="<?= site_url('evaluation/'.$assignment->public_code.'/profile') ?>">แก้ไขข้อมูล</a></div>
<div class="status-row"><span>ข้อมูลส่วนตัว</span><strong class="<?= $confirmed?'text-success':'text-warning' ?>"><?= $confirmed?'✓ ตรวจสอบแล้ว':'รอยืนยัน' ?></strong></div><div class="status-row"><span>แบบประเมิน</span><strong class="<?= $completed?'text-success':'text-warning' ?>"><?= $completed?'✓ ส่งเรียบร้อย':'ยังไม่ได้ทำ' ?></strong></div><div class="status-row"><span>สถานะเข้าอบรม</span><strong class="<?= $attended?'text-success':'text-secondary' ?>"><?= $attended?'✓ ยืนยันแล้ว':'รอเจ้าหน้าที่' ?></strong></div><div class="status-row"><span>วุฒิบัตร</span><strong class="<?= $certificate?'text-success':'text-secondary' ?>"><?= $certificate?'✓ '.$certificate->certificate_no:($ready?'รอเจ้าหน้าที่ออกวุฒิบัตร':'ยังไม่พร้อม') ?></strong></div>
<div class="d-grid gap-2 mt-4"><?php if(!$confirmed): ?><a class="btn btn-primary btn-lg" href="<?= site_url('evaluation/'.$assignment->public_code.'/confirm') ?>">ยืนยันข้อมูลถูกต้อง</a><?php endif; ?><?php if($confirmed&&!$completed&&$evaluation_state==='open'): ?><a class="btn btn-success btn-lg" href="<?= site_url('evaluation/'.$assignment->public_code.'/form') ?>">ทำแบบประเมิน</a><?php elseif(!$completed&&$evaluation_state==='closed'): ?><button class="btn btn-secondary btn-lg" disabled>แบบประเมินปิดรับคำตอบแล้ว</button><?php endif; ?><?php if($certificate): ?><a class="btn btn-outline-primary btn-lg" href="<?= site_url('evaluation/'.$assignment->public_code.'/certificate') ?>">ดาวน์โหลดวุฒิบัตร</a><?php else: ?><button class="btn btn-outline-primary btn-lg" disabled>ดาวน์โหลดวุฒิบัตร</button><small class="text-center text-secondary"><?= $ready?'รอเจ้าหน้าที่ออกวุฒิบัตร':'กรุณาดำเนินการให้ครบทุกเงื่อนไข' ?></small><?php endif; ?></div></div></div>
